// Keep direct observation words for body/toy facts only; garment names and colours come from the description, without the appended tags.
const FACT_WORDS = new Set("nipples topless boobs genitals anus anal ass buttocks nude toy".split(" "));
export const evidenceText = (desc: string, words: Iterable<string> = []) => `${affirmed(desc.replace(/\s*\(tags:[^)]*\)/gi, "")).text}\n${[...words].filter((w) => FACT_WORDS.has(w)).join(" ")}`;

/** The unsupported claims in ONE sentence (empty = fine). A negated clause ("i dont have a bikini one") makes no claim about the file. */
export function unsupported(sentence: string, ev: Set<string>): string[] {
  const bad: string[] = [];
  const clauses = sentence.toLowerCase().replace(/[’]/g, "'").split(/[,;:]|\bbut\b|\band\b(?=\s+(?:i|my|im|i'm|her|the|this|these)\b)/);
  for (const c of clauses) {
    for (const [pose, pattern] of POSES) {
      for (const match of c.matchAll(pattern)) {
        if (!ev.has(pose) && !NEG.test(c.slice(0, match.index))) bad.push(match[0]);
      }
    }
    const t = toks(c);
    t.forEach((w, i) => {
      const f = FAMILIES[w];
      if (!f) return;
      if (NEG.test(t.slice(0, i).join(" "))) return; // "no bra", "dont have a tank top one": an absence / denial
      if (!ev.has(f)) bad.push(w);
      else {
        for (const colour of coloursBefore(t, i)) if (!ev.has(`${colour}:${f}`)) bad.push(`${colour} ${w}`);
      }
    });
    // a colour before an unsupported word was already reported through that word
  }
  return [...new Set(bad)];
}

/** Drops every sentence that attributes something to the file that it does not show. Text with no such word is returned unchanged. */
export function groundReply(text: string, descAndWords: string | null, context: { availability?: Availability; prior?: string } = {}): { text: string; dropped: { sentence: string; claims: string[] }[] } {
  const ev = evidenceFamilies(descAndWords ?? "");
  const parts = text.split(/(?<=[.!?])\s+|\n+/);
  const keep: string[] = [], dropped: { sentence: string; claims: string[] }[] = [];
  for (const s of parts) {
    const t = s.toLowerCase().replace(/[’]/g, "'");
    const claims: string[] = [];
    // Bounded checks for broad stock denials only. A specific absence ("no blue bikini
    // photo"), a relative/friend count or a hypothetical is not a catalogue-wide denial.
    const a = context.availability;
    if (a) {
      const kind = /\b(?:videos?|vids?|clips?)\b/.test(t) ? "video" : "photo";
      const count = kind === "video" ? a.videos : a.photos;
      const noMore = /\b(?:no|dont have|don't have|do not have|havent got|haven't got)\s+(?:(?:any|more|other)\s+)*(?:photos?|pics?|pictures?|videos?|vids?|clips?)\b(?!\s+(?:in|with|of|wearing|showing)\b)|\b(?:out of|ran out of)\s+(?:photos?|pics?|videos?|clips?)\b/i.test(t);
      const onlyOne = /\bi(?:'ve|ve)?\s+(?:(?:only|just)\s+(?:got|have)|(?:have|got)\s+(?:only|just))\s+(?:(?:that|this|the|a)\s+)?(?:one|1)(?:\s+(?:photo|pic|picture|video|clip))?(?=\s*(?:[.,!?]|$|\b(?:babe|baby|sorry)\b))/i.test(t);
      if ((count > 0 && noMore) || (count > 1 && onlyOne)) claims.push("stock claim contradicts remaining availability");
    }
    // Delivery receipts cannot establish visibility, and a restart cannot guarantee a fix.
    if (/\b(?:it|(?:the|that|this) (?:photo|pic|card))\s+(?:is|should be|must be|will be)\s+(?:right\s+)?(?:there|in)\b.{0,45}\b(?:chat|visible|see|tap)\b/.test(t)) claims.push("unverified card visibility");
    if (/\b(?:telegram|app|restart|reopen|reopening)\b/.test(t)
      && /\b(?:always|every time|definitely|guaranteed)\b|\bwill\s+fix\b/.test(t)
      && /\b(?:fix|fixes|work|works)\b/.test(t)) claims.push("unsupported recovery guarantee");
    if (descAndWords !== null) claims.push(...unsupported(s, ev));
    else {
      const fileClaim = /\b(?:the|this|that|a)\s+(?:photo|pic|picture|shot|selfie|video|clip)\b|\b(?:photo|pic|picture|shot|selfie|video|clip)\s+(?:of me|in my|with my)\b|\b(?:the|this|that|a)\s+one\s+(?:of me|in my|with my|where i)\b/.test(t);
      const hypothetical = /\b(?:imagine|imagining|wish|wishing|if (?:u|you|i) (?:wanted|had|were)|would (?:u|you) (?:want|like|prefer) a)\b/.test(t);
      const past = /\b(?:sent|showed|shared|earlier|previous|last time)\b/.test(t);
      const details = unsupported(s, new Set()).length > 0 || /\b(?:photo|pic|picture|one) of me\b/.test(t);
      if (fileClaim && (details || past) && !hypothetical && !/\b(?:dont|don't|do not|no|not|cant|can't|cannot)\b/.test(t)) {
        if (past && context.prior) claims.push(...unsupported(s, evidenceFamilies(context.prior)));
        else claims.push(past ? "no recorded photo supports the past-send claim" : "file description without a selected attachment");
      }
    }
    if (claims.length) dropped.push({ sentence: s, claims }); else keep.push(s);
  }
  return dropped.length ? { text: keep.join(" ").trim(), dropped } : { text, dropped };
}

