    M.reply=JSON.stringify({selection:'none',reply:'that movie was pretty funny'});
    await rig.fan(82,'how did you like the movie',route);
    M.reply=JSON.stringify({selection:'none',reply:'what kind of movie do you want'});
    await rig.fan(82,'Can I have a different one',route);
    check('changed topic does not reuse stale photo context',()=>assert(M.bodies.at(-1).response_format.json_schema.schema.properties.selection.enum.includes('none')));
    check('changed topic sends no photo',()=>assert(!rig.rows().at(-1).media));
    rig.stop();
  }
  {
    const rig=verifiedRig();rig.deps.catalogue=cat;
    M.reply=JSON.stringify({selection:'photo 1',reply:'here is the photo'});
    await rig.fan(83,'show me a photo in a pink skirt',{bcid:'shared-business'});
    const receipt=runAs(rig.slug,()=>loadChat(83)).photo;
    check('past-reference seed is acknowledged',()=>assert.equal(receipt?.status,'acknowledged'));
    const item=cat.find(x=>x.key===receipt?.key)!;
    M.reply=JSON.stringify({selection:'none',reply:'the photo i sent earlier shows my pink skirt'});
    await rig.fan(83,'what did that previous photo show',{bcid:'shared-business'});
    check('grounded acknowledged past description survives',()=>assert(rig.rows().at(-1).final.join(' ').includes('pink skirt')));
    M.reply=JSON.stringify({selection:'none',reply:'the photo i sent earlier shows a blue bikini. it was a fun day'});
    await rig.fan(83,'what did that previous photo show',{bcid:'shared-business'});
    check('invented past description is removed',()=>assert(!rig.rows().at(-1).final.join(' ').includes('blue bikini')));
    check('unrelated valid text survives past-description filter',()=>assert(rig.rows().at(-1).final.join(' ').includes('fun day')));
    check('grounding leaves persisted receipt unchanged',()=>assert.equal(runAs(rig.slug,()=>loadChat(83)).photo?.key,item.key));
    rig.stop();
  }
  check('test creates no live state',()=>assert(config.dataDir.startsWith(tmp)&&config.logDir.startsWith(tmp)));
}finally{
  restoreFetch();M.rawStructured=original.raw;config.dataDir=original.data;config.logDir=original.logs;
  if(original.price===undefined)delete process.env.STAR_PRICE;else process.env.STAR_PRICE=original.price;
  fs.rmSync(tmp,{recursive:true,force:true});
}
console.log(JSON.stringify({stage:process.argv.includes('--baseline')?'baseline':'candidate',checks,failures}));
if(process.argv.includes('--baseline'))assert(failures.length>=8,'Known baseline failures must remain visible');else assert.equal(failures.length,0,failures.join('\n'));
